        this.networkUnsubscribers.push(
            multiplayerClient.onVulcanFiringState((state: NetworkVulcanFiringState) => {

                /*
                 * V518: remote spectators need the Vulcan firing presentation too.
                 */
                if (
                    state.active
                ) {
                    this.remoteVulcanFiringSessionIds
                        .add(
                            state.shooterId,
                        );
                } else {
                    this.remoteVulcanFiringSessionIds
                        .delete(
                            state.shooterId,
                        );
                }

                
                const localVulcanId =
                    multiplayerClient.getSessionId();

                if (
                    state.shooterId ===
                    localVulcanId
                ) {
                    const now =
                        Date.now();

                    /*
                     * V521 ONE HEAT SOURCE OF TRUTH:
                     * The same server HEAT that decides whether firing is legal
                     * drives the local bar. No independent accumulated total can
                     * silently drift and later jump to 100%.
                     */
                    const serverHeat =
                        Phaser.Math.Clamp(
                            Number(
                                state.heat,
                            ) ||
                                0,
                            0,
                            1,
                        );

                    this.vulcanHeat =
                        serverHeat;

                    this.vulcanHeatUpdatedAt =
                        now;

                    this.vulcanFiring =
                        state.active;

                    this.vulcanPointerHeld =
                        state.active;

                    if (
                        state.active
                    ) {
                        this.vulcanOverheated =
                            false;

                        this.vulcanReadyAt =
                            0;

                        this.vulcanFireStartedAt =
                            now -
                            Math.max(
                                0,
                                state.serverNow -
                                    state.startedAt,
                            );
                    } else if (
                        state.cooldownMs >=
                            2_990 ||
                        serverHeat >=
                            0.999
                    ) {
                        this.vulcanOverheated =
                            true;

                        this.vulcanHeat =
                            1;

                        this.vulcanReadyAt =
                            now +
                            Math.max(
                                0,
                                state.readyAt -
                                    state.serverNow,
                            );
                    } else {
                        this.vulcanOverheated =
                            false;

                        this.vulcanReadyAt =
                            0;
                    }

                    return;
                }
const localId =
                    multiplayerClient.getSessionId();

                if (
                    state.shooterId !==
                    localId
                ) {
                    return;
                }

                const now =
                    Date.now();

                if (
                    state.active
                ) {
                    this.vulcanFiring =
                        true;

                    this.vulcanPointerHeld =
                        true;

                    this.vulcanFireStartedAt =
                        now -
                        Math.max(
                            0,
                            state.serverNow -
                                state.startedAt,
                        );


                    this.vulcanCoolingDurationMs =
                        0;

                    return;
                }

                this.vulcanFiring =
                    false;

                this.vulcanPointerHeld =
                    false;

                this.vulcanHeat =
                    Phaser.Math.Clamp(
                        state.heldMs /
                            3000,
                        0,
                        1,
                    );


                this.vulcanCoolingDurationMs =
                    Math.max(
                        0,
                        state.cooldownMs,
                    );

                this.vulcanReadyAt =
                    now +
                    Math.max(
                        0,
                        state.readyAt -
                            state.serverNow,
                    );
            }),
        );

