    private openJoinRoomModal(
        roomId: string,
        isPrivate: boolean,
        fromInvite = false,
    ): void {
        multiplayerClient
            .prewarmServer();

        /*
         * 이전 실패 요청에서 transition flag가 남아 있더라도
         * 방 선택/모달 표시 자체는 항상 가능해야 합니다.
         * 실제 중복 네트워크 요청은 submitJoinRoom()에서 막습니다.
         */
        if (
            !multiplayerClient.isConnected()
        ) {
            this.roomTransitionInProgress =
                false;
        }
        const fields: Array<{
            key: string;
            label: string;
            value?: string;
            type?: 'text' | 'password';
        }> = [];

        if (isPrivate) {
            fields.push({
                key: 'password',
                label: tr('비밀번호'),
                type: 'password',
            });
        }

        fields.push({
            key: 'playerName',
            label: tr('닉네임'),
            value:
                this.getSavedPlayerName(),
        });

        this.createMenuModal(
            fromInvite
                ? tr('초대받은 방 참가')
                : tr('게임방 참가'),
            fields,
            tr('참가'),
            (values) => {
                void this.submitJoinRoom(
                    roomId,
                    isPrivate,
                    values,
                );
            },
        );
    }

